import React, { useContext, useState, useEffect, useMemo, useRef, useCallback } from 'react'
import HeaderTitle from '../../../Constants/Common/Layout/Header'
import { InputText } from 'primereact/inputtext'
import { ThemeContext } from '../../../Context/ThemeContext'
import { Dropdown } from 'primereact/dropdown'
import { Button } from 'primereact/button'
import { Versions } from '../../../Constants/Common/Layout/Header'
import { useNavigate } from 'react-router-dom'
import { DOCS } from '../../../Constants/docs'
import { Menu } from 'primereact/menu'
import { Dialog } from 'primereact/dialog'

const DocHeader = () => {
  const { 
    direction, 
    isDarkMode, 
    theme, 
    availableThemes, 
    setThemeWithMode 
  } = useContext(ThemeContext);
  const navigate = useNavigate();
  const [selectedVersion, setSelectedVersion] = useState(Versions[0].value);
  const [isSticky, setSticky] = useState(false)
  const [searchValue, setSearchValue] = useState('');
  const [isSearchDialogVisible, setSearchDialogVisible] = useState(false);
  const [highlightedResult, setHighlightedResult] = useState(0);
  const searchInputRef = useRef(null);
  const downloadMenuRef = useRef(null);
  const shortcutListenerRef = useRef(null);
  useEffect(() => {
    if (typeof window === 'undefined') {
      return undefined;
    }

    const handleKeyShortcut = (event) => {
      const isMac = navigator?.platform?.toUpperCase?.().includes('MAC');
      const isShortcut = isMac ? event.metaKey : event.ctrlKey;
      if (isShortcut && event.key.toLowerCase() === 'k') {
        event.preventDefault();
        setSearchDialogVisible(true);
      }
    };

    window.addEventListener('keydown', handleKeyShortcut);
    shortcutListenerRef.current = handleKeyShortcut;
    return () => {
      if (shortcutListenerRef.current) {
        window.removeEventListener('keydown', shortcutListenerRef.current);
      }
    };
  }, []);

  useEffect(() => {
    const handleScroll = () => {
      if (window.window.scrollY > 100) {
        setSticky(true)
      } else {
        setSticky(false)
      }
    }

    window.addEventListener('scroll', handleScroll)

    return () => {
      window.removeEventListener('scroll', handleScroll)
    }
  }, [])

  const searchableDocs = useMemo(() => (
    DOCS
      .map(doc => ({
        label: doc.menuItem,
        route: doc.routeBase,
        category: doc.category,
        subCategory: doc.subCategory,
        keywords: `${doc.menuItem} ${doc.category ?? ''} ${doc.subCategory ?? ''}`.toLowerCase()
      }))
      .sort((a, b) => a.label.localeCompare(b.label))
  ), []);

  const trimmedQuery = searchValue.trim().toLowerCase();

  const searchResults = useMemo(() => {
    if (!trimmedQuery) {
      return [];
    }

    return searchableDocs.filter(doc => doc.keywords.includes(trimmedQuery)).slice(0, 8);
  }, [trimmedQuery, searchableDocs]);

  const featuredSuggestions = useMemo(() => {
    const featuredLabels = [
      'Button',
      'Input Text',
      'Dialog',
      'Card',
      'DataTable',
      'Theme System'
    ];

    return featuredLabels
      .map((label) => searchableDocs.find((doc) => doc.label === label))
      .filter(Boolean);
  }, [searchableDocs]);

  useEffect(() => {
    setHighlightedResult(0);
  }, [searchValue, isSearchDialogVisible]);

  const downloadBasePath = useMemo(() => {
    const base = import.meta.env.BASE_URL ?? '/';
    return base.endsWith('/') ? base.slice(0, -1) : base;
  }, []);

  const downloadOptions = useMemo(() => ([
    {
      label: 'Download ULS',
      href: `${downloadBasePath}/downloads/uls.zip`
    },
    {
      label: 'Download PrimeReact bundle',
      href: `${downloadBasePath}/downloads/uls-primereact.zip`
    },
    {
      label: 'Download styles (.css)',
      href: `${downloadBasePath}/downloads/uls-styles-css.zip`
    }
  ]), [downloadBasePath]);

  const handleDownload = useCallback((href) => {
    const tempLink = document.createElement('a');
    tempLink.href = href;
    tempLink.setAttribute('download', '');
    document.body.appendChild(tempLink);
    tempLink.click();
    document.body.removeChild(tempLink);
  }, []);

  const downloadMenuItems = useMemo(() => (
    downloadOptions.map(option => ({
      label: option.label,
      key: option.href,
      template: (item, menuOptions) => (
        <a
          className='menu-action'
          href={option.href}
          download
          onClick={(event) => {
            menuOptions.onClick?.(event);
            handleDownload(option.href);
          }}
        >
          <span className='medium-font'>{option.label}</span>
          <span className='font-size12 fg-text-secondary block'>{option.description}</span>
        </a>
      )
    }))
  ), [downloadOptions, handleDownload]);

  const handleSearchChange = (event) => {
    setSearchValue(event.target.value);
  };

  const handleNavigateToResult = useCallback((result) => {
    if (!result) {
      return;
    }

    navigate(result.route);
    setSearchValue('');
    setSearchDialogVisible(false);
  }, [navigate]);

  const hasQuery = trimmedQuery.length > 0;
  const activeResults = hasQuery ? searchResults : featuredSuggestions;

  const handleSearchKeyDown = (event) => {
    if (!activeResults.length) {
      return;
    }

    if (event.key === 'ArrowDown') {
      event.preventDefault();
      setHighlightedResult((prev) => (prev + 1) % activeResults.length);
    } else if (event.key === 'ArrowUp') {
      event.preventDefault();
      setHighlightedResult((prev) => (prev - 1 + activeResults.length) % activeResults.length);
    } else if (event.key === 'Enter') {
      event.preventDefault();
      handleNavigateToResult(activeResults[highlightedResult] ?? activeResults[0]);
    } else if (event.key === 'Escape') {
      setSearchDialogVisible(false);
    }
  };

  const shouldShowResults = isSearchDialogVisible && activeResults.length > 0;

  const buildMenuItems = (results) => results.map((result, index) => {
    const descriptor = [result.category, result.subCategory].filter(Boolean).join(' • ');
    const isActive = index === highlightedResult;

    return {
      key: `${result.route}-${index}`,
      template: () => (
        <button
          type="button"
          className='t-search-result-item menu-action w-100p fxb fhs pd8'
          onMouseDown={(event) => event.preventDefault()}
          onMouseEnter={() => setHighlightedResult(index)}
          onClick={() => handleNavigateToResult(result)}
          
        >
          <span className='medium-font'>{result.label}</span>
          <span className='font-size12 fg-text-secondary'>
            {descriptor || 'Component'}
          </span>
        </button>
      )
    };
  });

  const renderSearchResults = () => {
    if (!hasQuery && featuredSuggestions.length) {
      return (
        <div className='t-featured-suggestions'>
          <div className='fxb fvc fsb gp4 mgb5'>
            <p className='fg-text-secondary bold-font font-size15'>
              Featured components
            </p>
          </div>
          <Menu model={buildMenuItems(featuredSuggestions)} className='t-search-menu w-100p' />
        </div>
      );
    }

    if (!activeResults.length) {
      return (
        <p className='fg-text-secondary font-size14 mgb2'>
          No matches for <strong>{searchValue}</strong>. Try another keyword.
        </p>
      );
    }

    return (
      <Menu model={buildMenuItems(activeResults)} className='t-search-menu w-100p' />
    );
  };

  useEffect(() => {
    if (isSearchDialogVisible) {
      setTimeout(() => searchInputRef.current?.focus(), 100);
    }
  }, [isSearchDialogVisible]);

  const themeOptions = availableThemes.map(themeOption => ({
    label: themeOption.label,
    value: `${themeOption.name}-${themeOption.isDark}`,
    themeName: themeOption.name,
    isDark: themeOption.isDark
  }));

  const currentThemeKey = `${theme}-${isDarkMode}`;

  const handleThemeToggle = useCallback(() => {
    if (!themeOptions.length) {
      return;
    }

    const currentIndex = themeOptions.findIndex(option => option.value === currentThemeKey);
    const nextIndex = currentIndex === -1 ? 0 : (currentIndex + 1) % themeOptions.length;
    const nextTheme = themeOptions[nextIndex];
    setThemeWithMode(nextTheme.themeName, nextTheme.isDark);
  }, [currentThemeKey, themeOptions, setThemeWithMode]);


  return (
  <>
    {/* SVG Filter with Minimal Turbulence */}
    <svg style={{ display: 'none' }}>
      {/* Minimal Turbulence Filter */}
      <filter id="lg-minimal" x="0%" y="0%" width="100%" height="100%">
        <feTurbulence type="fractalNoise" baseFrequency="0.003 0.003" numOctaves="1" seed="2" result="noise" />
        <feGaussianBlur in="noise" stdDeviation="1" result="blurred" />
        <feDisplacementMap in="SourceGraphic" in2="blurred" scale="50" xChannelSelector="R" yChannelSelector="G" />
      </filter>
    </svg>
    
    <div 
      className={`ulsp-topbar h64 pd2 uls-grid col-1 ${isSticky ? 'sticky w-100p' : ''}`}
      style={{
        // Completely remove background-color to let CSS liquid glass effect work
        backgroundColor: isSticky ? 'transparent' : `${isDarkMode ? 'hsla(0,0%,20%,.3)' : 'hsla(0, 0.00%, 100.00%, 0.50)'}`
      }}
    >
      <header className="uls-container-fluid fxb fvc fsb">
        <div className='t-left'>
          <div className='t-logo'>
            <h3 className='bold-font'>{HeaderTitle.label} <span className='fg-primary'>{HeaderTitle.primaryLabel}</span></h3>
          </div>
        </div>
        <div className='t-right fxb fvc gp4'>
          
          <div 
            className={`t-search ${direction === 'ltr' ? 'mgl2' : 'mgr2'}`} 
            style={{ position: 'relative' }}
          >
            <button
              type="button"
              className='uls-button secondary  outlined s-size fxb fvc gp2'
              onClick={() => setSearchDialogVisible(true)}
              aria-haspopup="dialog"
              aria-expanded={isSearchDialogVisible}
            >
              <i className='pi pi-search font-size14' aria-hidden="true"></i>
              <span className='fg-text-secondary'>Search docs</span>
              <span className='t-key-hint mgl3'>⌘ K</span>
            </button>
            <Dialog
              header="Search ULS docs"
              visible={isSearchDialogVisible}
              onHide={() => setSearchDialogVisible(false)}
              className='doc-search-dialog'
              pt={{
                content: {
                  className: 'w-100p'
                }
              }}
              dismissableMask
              blockScroll
            >
              <div className='t-search-dialog-body'>
                <InputText
                  value={searchValue}
                  onChange={handleSearchChange}
                  onKeyDown={handleSearchKeyDown}
                  placeholder='Search components'
                  aria-label='Search components'
                  className='w-100p mgb3'
                  inputRef={searchInputRef}
                />
                <div className='fg-text-secondary font-size12 medium-font mgb3 mgt12 '>
                  Showing {shouldShowResults ? activeResults.length : 0} result{activeResults.length === 1 ? '' : 's'}
                </div>
                {renderSearchResults()}
              </div>
            </Dialog>
          </div>
          {/* <div className={`t-user ${direction === 'ltr' ? 'mgl2' : 'mgr2'}`}>
            <Dropdown 
              value={selectedVersion}
              onChange={(e) => setSelectedVersion(e.value)} 
              options={Versions} 
              optionValue="value"
              optionLabel="label"
              className='uls-dropdown'
            />
          </div> */}
          
          <div className={`t-download ${direction === 'ltr' ? 'mgl2' : 'mgr2'}`}>
            <Menu
              id="doc-download-menu"
              model={downloadMenuItems}
              popup
              ref={downloadMenuRef}
            />
            <button
              type="button"
              className='uls-button primary fxb fvc gp2 m-size'
              onClick={(event) => downloadMenuRef.current?.toggle(event)}
              aria-haspopup="menu"
              aria-controls="doc-download-menu"
            >
              <i className='pi pi-download font-size14' aria-hidden="true"></i>
              <span>Download ZIP</span>
              <i className='pi pi-chevron-down' aria-hidden="true"></i>
            </button>
          </div>

          <div className={`t-theme-switcher ${direction === 'ltr' ? 'mgl2' : 'mgr2'}`}>
            <Button
              icon={isDarkMode ? 'pi pi-sun' : 'pi pi-moon'}
              className='pd3'
              outlined
              severity='secondary'
              aria-label={isDarkMode ? 'Switch to light theme' : 'Switch to dark theme'}
              onClick={handleThemeToggle}
            />
          </div>
        </div>
      </header>
    </div>
  </>
  );  
};

export default DocHeader;
